package control

import "net/http"

const dashboardHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pearl Fleet</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{font:14px system-ui;background:#07111f;color:#e5eefc;margin:0}main{max-width:1500px;margin:28px auto;padding:0 18px}
h1{font-size:27px;margin-bottom:4px}.muted{color:#91a4bf}.bar{display:flex;gap:8px;margin:16px 0;flex-wrap:wrap;align-items:center}
button,input,select{background:#13243b;color:#fff;border:1px solid #355174;border-radius:7px;padding:8px}button{cursor:pointer}button:hover{background:#1b3353}
.panel{background:#0d1a2b;border:1px solid #21354f;border-radius:10px;padding:12px;margin:12px 0;overflow:auto}
table{width:100%;border-collapse:collapse;min-width:1050px}th,td{padding:9px;border-bottom:1px solid #21354f;text-align:left;vertical-align:top}.ok{color:#4ade80}.off{color:#fbbf24}.bad{color:#fb7185}.gpu{white-space:nowrap;font-size:12px}.health{max-width:220px}.audit{font-family:ui-monospace,monospace;font-size:12px;white-space:pre-wrap}
@media(max-width:720px){main{padding:0 10px;margin-top:16px}.bar>*{flex:1}.panel{padding:8px}}
</style></head><body><main><h1>Pearl Fleet</h1>
<p class="muted">Owner-authorized PRL fleet control. Commands are allowlisted and audited.</p>
<div class="bar"><input id="token" type="password" placeholder="Admin token" size="42"><button onclick="saveToken();loadAgents()">Refresh</button><span id="summary" class="muted"></span></div>
<div class="bar"><button onclick="batch('start')">Start selected</button><button onclick="batch('stop')">Stop selected</button><button onclick="batch('resume')">Resume policy</button><select id="batchMode"><option>smart</option><option>avoid</option><option>full</option><option>manual</option></select><button onclick="batch('set-mode',{mode:document.getElementById('batchMode').value})">Set mode</button><button onclick="loadAudit()">Audit log</button></div>
<div class="panel"><table><thead><tr><th><input type="checkbox" onchange="selectAll(this.checked)"></th><th>Agent</th><th>Status</th><th>Mode</th><th>Hashrate</th><th>Shares</th><th>GPU</th><th>Use</th><th>Health</th><th>Actions</th></tr></thead><tbody id="agents"></tbody></table></div>
<div id="auditPanel" class="panel" hidden><strong>Recent audit events</strong><div id="audit" class="audit"></div></div>
<script>
const selected=new Set();const token=document.getElementById('token');token.value=sessionStorage.getItem('pearlAdminToken')||'';
function saveToken(){sessionStorage.setItem('pearlAdminToken',token.value)}
async function api(path,options={}){saveToken();options.headers={...(options.headers||{}),'Authorization':'Bearer '+token.value,'Content-Type':'application/json'};const r=await fetch(path,options);if(!r.ok)throw new Error(await r.text());return r.json()}
async function command(id,type,payload={}){await api('/api/v1/admin/agents/'+encodeURIComponent(id)+'/commands',{method:'POST',body:JSON.stringify({type,payload})});await loadAgents()}
async function batch(type,payload={}){if(!selected.size)return alert('Select at least one agent');await api('/api/v1/admin/commands/batch',{method:'POST',body:JSON.stringify({agent_ids:[...selected],type,payload})});await loadAgents()}
function selectAll(checked){document.querySelectorAll('[data-agent-check]').forEach(box=>{box.checked=checked;toggle(box.dataset.agentCheck,checked)})}function toggle(id,checked){checked?selected.add(id):selected.delete(id)}
async function configurePolicy(id){const idle=prompt('Start after idle seconds (blank keeps current)','300');if(idle===null)return;const games=prompt('Blocked process names, comma separated (blank keeps current)','');const payload={};if(idle!=='')payload.start_idle_seconds=idle;if(games!=='')payload.blocked_processes=games;if(Object.keys(payload).length)await command(id,'set-policy',payload)}
async function configureMining(id){const pool=prompt('PearlHash pool host:port (blank keeps current)','');if(pool===null)return;const wallet=prompt('PRL payout address (blank keeps current)','');const power=prompt('Power limit W; 0 lets the miner or driver decide (blank keeps current)','');const payload={};if(pool!=='')payload.pool=pool;if(wallet!=='')payload.wallet=wallet;if(power!=='')payload.power_limit=power;if(Object.keys(payload).length)await command(id,'set-mining',payload)}
async function configureGPU(id){const index=prompt('GPU index','0');if(index===null)return;const power=prompt('Power limit W; blank leaves unchanged','');const core=prompt('Core offset MHz; blank leaves unchanged','');const memory=prompt('Memory offset MHz; blank leaves unchanged','');const fan=prompt('Fan percent; blank leaves unchanged','');const payload={index};if(power!=='')payload.power_limit=power;if(core!=='')payload.core_offset=core;if(memory!=='')payload.memory_offset=memory;if(fan!=='')payload.fan_speed=fan;await command(id,'set-gpu-profile',payload)}
async function loadAgents(){try{const agents=await api('/api/v1/admin/agents');const body=document.getElementById('agents');body.innerHTML='';let onlineCount=0,miningCount=0;for(const a of agents){const h=a.last_heartbeat;const online=h&&(Date.now()-new Date(h.time).getTime()<90000);if(online)onlineCount++;if(h?.miner_running)miningCount++;const tr=document.createElement('tr');const gpus=(h?.gpus||[]).map(g=>esc('#'+g.index+' '+g.name)+'<br><span class="muted">'+esc(g.temperature_c)+'°C · '+esc(g.power_watts)+'W</span>').join('<br>')||'-';const last=(a.commands||[]).slice(-1)[0];const commandState=last?(last.result||'pending')+(last.message?': '+last.message:''):'-';tr.innerHTML='<td><input data-agent-check="'+esc(a.id)+'" type="checkbox"></td><td><strong>'+esc(a.id)+'</strong><br><span class="muted">v'+esc(h?.version||'-')+'</span></td><td class="'+(online?'ok':'off')+'">'+(online?'online':'offline')+'<br><span class="muted">'+(h?.miner_running?'mining':'stopped')+'</span></td><td>'+esc(h?.policy_mode||'-')+'<br><span class="muted">'+esc(h?.reason||'-')+'</span></td><td>'+rate(h?.hashrate_10s)+'</td><td>'+esc(h?.accepted_shares??0)+' / '+esc(h?.rejected_shares??0)+'</td><td class="gpu">'+gpus+'</td><td>'+esc(h?.idle_seconds??'-')+'s idle<br><span class="muted">'+esc(h?.foreground||'-')+'</span></td><td class="health '+(String(h?.health||'').startsWith('ok')?'ok':'bad')+'">'+esc(h?.health||'-')+'<br><span class="muted">last cmd '+esc(commandState)+'</span></td><td><button data-c="start">Start</button> <button data-c="stop">Stop</button> <button data-c="resume">Resume</button><br><select><option>smart</option><option>avoid</option><option>full</option><option>manual</option></select> <button data-c="mode">Mode</button><br><button data-c="policy">Policy</button> <button data-c="mining">Mining</button><br><button data-c="gpu">Tune GPU</button> <button data-c="reset-gpu-profiles">Reset tuning</button></td>';const box=tr.querySelector('[data-agent-check]');box.checked=selected.has(a.id);box.onchange=()=>toggle(a.id,box.checked);tr.querySelectorAll('button').forEach(b=>b.onclick=()=>b.dataset.c==='mode'?command(a.id,'set-mode',{mode:tr.querySelector('select').value}):b.dataset.c==='policy'?configurePolicy(a.id):b.dataset.c==='mining'?configureMining(a.id):b.dataset.c==='gpu'?configureGPU(a.id):command(a.id,b.dataset.c));body.appendChild(tr)}document.getElementById('summary').textContent=onlineCount+'/'+agents.length+' online · '+miningCount+' mining'}catch(e){alert(e.message)}}
async function loadAudit(){try{const events=await api('/api/v1/admin/audit?limit=100');const panel=document.getElementById('auditPanel');panel.hidden=false;document.getElementById('audit').textContent=events.slice().reverse().map(e=>e.time+'  '+e.action+'  '+(e.agent_id||'')+'  '+(e.sequence||'')+'  '+JSON.stringify(e.details||{})).join('\n')}catch(e){alert(e.message)}}
function rate(v){return v?Number(v).toLocaleString(undefined,{maximumFractionDigits:2})+' H/s':'-'}function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
</script></main></body></html>`

func (s *Server) dashboard(writer http.ResponseWriter, _ *http.Request) {
	writer.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = writer.Write([]byte(dashboardHTML))
}
